#!/bin/bash
# tests/manual/bash-first-steer/summarize-run.sh
#
# Print the observable outcome of one run directory produced by run-case.sh.
# Usage: summarize-run.sh <exp-root> <case-id>
set -euo pipefail
EXP_ROOT="${1:?usage: summarize-run.sh <exp-root> <case-id>}"
CASE="${2:?case-id}"
OUT="$EXP_ROOT/runs/$CASE"
REPO="$OUT/repo"
[[ -f "$OUT/meta.txt" ]] || { echo "no such run: $OUT" >&2; exit 1; }
# tokens.env is generated by make-fixture.sh; read the three values instead of
# sourcing the file as shell code.
_token() { sed -n "s/^$1=\([A-Za-z0-9-]*\)$/\1/p" "$EXP_ROOT/tokens.env" | head -1; }
UNCOND_TOKEN="$(_token UNCOND_TOKEN)"; PATHRULE_TOKEN="$(_token PATHRULE_TOKEN)"; NESTED_TOKEN="$(_token NESTED_TOKEN)"
[[ -n "$UNCOND_TOKEN" && -n "$PATHRULE_TOKEN" && -n "$NESTED_TOKEN" ]] || { echo "tokens.env is incomplete" >&2; exit 1; }
# Best-effort sections below must not abort the summary on a missing file.
set +e

echo "################ $CASE ################"
cat "$OUT/meta.txt"
echo "--- steer attachment (auto_mode; bashFirst=true means the Bash-first steer was injected) ---"
if [[ -s "$OUT/auto-mode-attachment.jsonl" ]]; then cat "$OUT/auto-mode-attachment.jsonl"; else echo "(none)"; fi
echo "--- result ---"
jq -c 'select(.type=="result") | {subtype,is_error,num_turns,duration_ms,total_cost_usd,
  permission_denials: [.permission_denials[]? | {tool_name, file: (.tool_input.file_path // null)}]}' \
  "$OUT/stdout.jsonl" 2>/dev/null
echo "--- tool calls (assistant tool_use blocks, in order) ---"
jq -r '
  select(.type=="assistant") | .message.content[]? | select(.type=="tool_use")
  | .name + "  " + (
      if .name=="Bash" then ((.input.command // "") | .[0:110] | gsub("\n"; "⏎"))
      elif (.input.file_path? // null) != null then (.input.file_path | sub(".*/repo/"; ""))
      else "" end)' "$OUT/stdout.jsonl" 2>/dev/null
echo "--- tool call counts ---"
jq -r 'select(.type=="assistant") | .message.content[]? | select(.type=="tool_use") | .name' \
  "$OUT/stdout.jsonl" 2>/dev/null | sort | uniq -c | sort -rn
echo "--- hook responses (name / exit / stderr / stdout) ---"
jq -r 'select(.type=="system" and .subtype=="hook_response")
  | .hook_name + "  exit=" + (.exit_code|tostring) + "  outcome=" + (.outcome // "")
    + (if (.stderr // "") != "" then "  stderr=" + ((.stderr|gsub("\n";" "))[0:140]) else "" end)
    + (if (.stdout // "") != "" then "  stdout=" + ((.stdout|gsub("\n";" "))[0:140]) else "" end)' \
  "$OUT/stdout.jsonl" 2>/dev/null | sort | uniq -c
echo "--- InstructionsLoaded (observer) ---"
jq -r 'select(.event=="InstructionsLoaded")
  | .load_reason + "  " + (.file_path | sub(".*/repo/"; ""))
    + (if .trigger_file_path then "  <- " + (.trigger_file_path | sub(".*/repo/"; "")) else "" end)' \
  "$OUT/observer.jsonl" 2>/dev/null
echo "--- rule/nested marker flags at repo root ---"
for t in "$UNCOND_TOKEN" "$PATHRULE_TOKEN" "$NESTED_TOKEN"; do
  if [[ -e "$REPO/$t.flag" ]]; then echo "present  $t.flag"; else echo "absent   $t.flag"; fi
done
echo "--- files ---"
for f in AGENTS.md SUMMARY.md; do
  if [[ -e "$REPO/$f" ]]; then echo "present  $f ($(wc -l < "$REPO/$f" | tr -d ' ') lines)"; else echo "absent   $f"; fi
done
echo "--- src/app.ts reformatted by a formatter hook (biome or prettier)? ---"
if grep -q '^const config = {' "$OUT/app.ts.after" 2>/dev/null; then echo "yes"; else echo "no"; fi
echo "--- git status ---"
cat "$OUT/git-status.txt"
echo "--- stderr (first 300 chars) ---"
head -c 300 "$OUT/stderr.txt"; echo
